#!/usr/bin/env node
/**
 * Cinejoy webOS - Milestone 4 Iteration 2 Adversarial Stress & Fuzzing Suite
 * File: tests/adversarial-m4-gen2-stress.js
 * 
 * Agent: challenger_m4_gen2_1
 * Roles: critic, specialist
 * 
 * Deep empirical stress testing of:
 * 1. Defect Regression: ADV-S4.2, ADV-S4.3, ADV-S4.5, ADV-S4.6, ADV-S4.7, ADV-S4.8, ADV-S4.9, ADV-S4.10, ADV-S4.14
 * 2. Edge Case & Payload Fuzzing: Nested corrupted payloads, null sub-arrays, extreme release dates, non-object cast
 * 3. Memory & Cache Bounds: 100 entries strict limit, ~350KB footprint, LRU eviction thrashing
 * 4. Timeouts & AbortController: 8000ms default timeout, timer cleanup, signal propagation
 */

'use strict';

const fs = require('fs');
const path = require('path');
const assert = require('assert');

// 1. Resolve JSDOM
let JSDOM;
try {
  JSDOM = require('jsdom').JSDOM;
} catch (e1) {
  try {
    JSDOM = require('/home/prem/monkeytype/monkeytype/node_modules/.pnpm/jsdom@27.4.0_supports-color@10.2.2/node_modules/jsdom').JSDOM;
  } catch (e2) {
    try {
      JSDOM = require('/home/prem/Documents/movies/netflix/node_modules/jsdom').JSDOM;
    } catch (e3) {
      console.error('FATAL: JSDOM module could not be resolved.');
      process.exit(1);
    }
  }
}

// 2. ANSI Formatting
const C = {
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  cyan: '\x1b[36m',
  yellow: '\x1b[33m',
  gray: '\x1b[90m'
};

let totalChecks = 0;
let passedChecks = 0;
let failedChecks = 0;
const failureList = [];

async function check(suiteId, testId, description, fn) {
  totalChecks++;
  const label = `[${suiteId}.${testId}] ${description}`;
  const start = Date.now();
  try {
    await fn();
    passedChecks++;
    const duration = Date.now() - start;
    console.log(`  ${C.green}✓ PASS${C.reset} ${label} ${C.gray}(${duration}ms)${C.reset}`);
  } catch (err) {
    failedChecks++;
    failureList.push({ label, error: err.message, stack: err.stack });
    console.log(`  ${C.red}✗ FAIL${C.reset} ${label}`);
    console.log(`    ${C.red}Error: ${err.message}${C.reset}`);
  }
}

function createFreshTmdb(config) {
  const resolved = path.resolve(__dirname, '../app/js/tmdb.js');
  delete require.cache[require.resolve(resolved)];
  const tmdb = require(resolved);
  if (config) {
    tmdb.init(config);
  }
  return tmdb;
}

async function runEmpiricalStressSuite() {
  console.log(`\n${C.bold}========================================================================${C.reset}`);
  console.log(`${C.bold}   CINEJOY-WEBOS: M4 GEN2 ADVERSARIAL STRESS & FUZZING HARNESS          ${C.reset}`);
  console.log(`${C.bold}   Agent: challenger_m4_gen2_1 (critic, specialist)                     ${C.reset}`);
  console.log(`${C.bold}========================================================================${C.reset}\n`);

  // ===========================================================================
  // SUITE 1: Defect Regression Verification (All 9 Defects)
  // ===========================================================================
  console.log(`${C.cyan}▶ SUITE 1: Defect Regression Verification (Zero Unhandled Exceptions)${C.reset}`);

  // ADV-S4.2
  await check('DEFECT', 'ADV-S4.2', 'Top-level null and primitive payloads across all 8 API endpoints', async function () {
    const tmdb = createFreshTmdb();
    tmdb.clearCache();

    const primitives = [null, undefined, 42, 'string_payload', true, false];
    for (const prim of primitives) {
      global.fetch = () => Promise.resolve({
        ok: true,
        json: () => Promise.resolve(prim)
      });

      // 1. getTrending
      const resTrending = await tmdb.getTrending('movie', 'day');
      assert.ok(resTrending && Array.isArray(resTrending.results), 'getTrending must return results array');

      // 2. getTopRated
      const resTopRated = await tmdb.getTopRated('tv');
      assert.ok(resTopRated && Array.isArray(resTopRated.results), 'getTopRated must return results array');

      // 3. discover
      const resDiscover = await tmdb.discover('movie', { page: 1 });
      assert.ok(resDiscover && Array.isArray(resDiscover.results), 'discover must return results array');

      // 4. getDetails
      const resDetails = await tmdb.getDetails('movie', 999);
      assert.strictEqual(typeof resDetails, 'object', 'getDetails must return object without throwing');

      // 5. getTvSeason
      const resSeason = await tmdb.getTvSeason(999, 1);
      assert.ok(resSeason && Array.isArray(resSeason.episodes), 'getTvSeason must return episodes array');

      // 6. searchMulti
      const resSearch = await tmdb.searchMulti('test');
      assert.ok(resSearch && Array.isArray(resSearch.results), 'searchMulti must return results array');

      // 7. getWingLists
      const resLists = await tmdb.getWingLists();
      assert.ok(Array.isArray(resLists), 'getWingLists must return array');

      // 8. getWingListItems
      const resListItems = await tmdb.getWingListItems('sample-list');
      assert.ok(resListItems && Array.isArray(resListItems.items), 'getWingListItems must return items array');
    }
  });

  // ADV-S4.3
  await check('DEFECT', 'ADV-S4.3', 'Corrupted results property (string, number, boolean, object) on list endpoints', async function () {
    const tmdb = createFreshTmdb();
    tmdb.clearCache();

    const corruptResults = ['corrupt_string', 12345, true, false, { a: 1, b: 2 }];
    for (const badRes of corruptResults) {
      global.fetch = () => Promise.resolve({
        ok: true,
        json: () => Promise.resolve({ page: 1, results: badRes })
      });

      const resTrending = await tmdb.getTrending('movie', 'day');
      assert.ok(Array.isArray(resTrending.results), 'getTrending must default to empty array');
      assert.strictEqual(resTrending.results.length, 0);

      const resTopRated = await tmdb.getTopRated('movie');
      assert.ok(Array.isArray(resTopRated.results), 'getTopRated must default to empty array');
      assert.strictEqual(resTopRated.results.length, 0);

      const resDiscover = await tmdb.discover('movie');
      assert.ok(Array.isArray(resDiscover.results), 'discover must default to empty array');
      assert.strictEqual(resDiscover.results.length, 0);

      const resSearch = await tmdb.searchMulti('query');
      assert.ok(Array.isArray(resSearch.results), 'searchMulti must default to empty array');
      assert.strictEqual(resSearch.results.length, 0);
    }
  });

  // ADV-S4.5
  await check('DEFECT', 'ADV-S4.5', 'Release date fuzzing: numeric, negative, null, empty, objects', async function () {
    const tmdb = createFreshTmdb();

    const dateCases = [
      { input: 2024, expectedYear: '2024' },
      { input: 1895, expectedYear: '1895' },
      { input: 0, expectedYear: '' },
      { input: -1, expectedYear: '-1' },
      { input: '2025-12-31', expectedYear: '2025' },
      { input: 'Circa 1990', expectedYear: 'Circ' },
      { input: null, expectedYear: '' },
      { input: undefined, expectedYear: '' },
      { input: '', expectedYear: '' },
      { input: { year: 2024 }, expectedYear: '[obj' }
    ];

    for (const tc of dateCases) {
      const item = tmdb.normalizeItem({ id: 1, title: 'Test', release_date: tc.input });
      assert.ok(item, 'Item must be normalized');
      assert.strictEqual(item.year, tc.expectedYear, `Year must match for input ${JSON.stringify(tc.input)}`);
    }
  });

  // ADV-S4.6
  await check('DEFECT', 'ADV-S4.6', 'Genres property fuzzing: non-array objects, strings, mixed arrays', async function () {
    const tmdb = createFreshTmdb();

    const genreCases = [
      { genres: { id: 28, name: 'Action' } },
      { genres: 'Action, Drama' },
      { genres: 123 },
      { genres: null },
      { genres: [null, undefined, { id: 28 }, { id: 'invalid' }, { name: 'NoId' }, 42] },
      { genre_ids: 'non_array_string' },
      { genre_ids: { '0': 28 } },
      { genre_ids: [28, null, undefined, 878, 'invalid'] }
    ];

    for (const gc of genreCases) {
      const item = tmdb.normalizeItem(Object.assign({ id: 2, title: 'Genre Test' }, gc));
      assert.ok(item, 'normalizeItem must handle corrupted genres');
      assert.ok(Array.isArray(item.genres), 'genres must always be array');
      assert.ok(Array.isArray(item.genreIds), 'genreIds must always be array');
    }
  });

  // ADV-S4.7
  await check('DEFECT', 'ADV-S4.7', 'Malformed credits & cast (cast is object, string, or contains non-objects)', async function () {
    const tmdb = createFreshTmdb();

    const malformedCredits = [
      { credits: null },
      { credits: { cast: null } },
      { credits: { cast: 'Timothee Chalamet' } },
      { credits: { cast: 12345 } },
      { credits: { cast: [null, undefined, 'Actor 1', 99, false, { id: 10, name: 'Real Actor', character: 'Hero' }, {}] } }
    ];

    for (const c of malformedCredits) {
      const details = tmdb.normalizeDetails(Object.assign({ id: 3, title: 'Cast Test' }, c));
      assert.ok(details, 'normalizeDetails must not return null');
      assert.ok(Array.isArray(details.cast), 'details.cast must always be an array');
    }
  });

  // ADV-S4.8
  await check('DEFECT', 'ADV-S4.8', 'Malformed recommendations & similar (non-array, null, or corrupted results)', async function () {
    const tmdb = createFreshTmdb();

    const malformedRecs = [
      { recommendations: null, similar: null },
      { recommendations: { results: 'none' }, similar: { results: 42 } },
      { recommendations: { results: [null, undefined, 'invalid', { id: 101, title: 'Valid 1' }] } },
      { similar: { results: [{ id: 201, title: 'Valid 2' }, null] } }
    ];

    for (const r of malformedRecs) {
      const details = tmdb.normalizeDetails(Object.assign({ id: 4, title: 'Recs Test' }, r));
      assert.ok(details, 'normalizeDetails must succeed');
      assert.ok(Array.isArray(details.recommendations), 'recommendations must be array');
      assert.ok(Array.isArray(details.similar), 'similar must be array');
      // Verify nulls are purged
      assert.ok(details.recommendations.every(Boolean), 'recommendations must not contain nulls');
      assert.ok(details.similar.every(Boolean), 'similar must not contain nulls');
    }
  });

  // ADV-S4.9
  await check('DEFECT', 'ADV-S4.9', 'Malformed logos (string, object, array of nulls/primitives)', async function () {
    const tmdb = createFreshTmdb();

    const logoCases = [
      null,
      undefined,
      {},
      { logos: null },
      { logos: 'logo_url_string' },
      { logos: 123 },
      { logos: [] },
      { logos: [null, undefined] },
      { logos: ['string_logo', 456] },
      { logos: [{ file_path: null }] },
      { logos: [{ file_path: '/valid_en.png', iso_639_1: 'en' }] }
    ];

    for (const lc of logoCases) {
      const logoUrl = tmdb.getLogoUrl(lc);
      if (lc && lc.logos && lc.logos[0] && lc.logos[0].file_path === '/valid_en.png') {
        assert.ok(logoUrl && logoUrl.includes('/valid_en.png'), 'Must resolve valid logo');
      } else {
        assert.strictEqual(logoUrl, null, `Must return null for invalid logo case ${JSON.stringify(lc)}`);
      }
    }
  });

  // ADV-S4.10
  await check('DEFECT', 'ADV-S4.10', 'Malformed TV season episodes (non-array, null items, primitives)', async function () {
    const tmdb = createFreshTmdb();
    tmdb.clearCache();

    const episodeFixtures = [
      { id: 100, episodes: null },
      { id: 101, episodes: 'not_an_array' },
      { id: 102, episodes: [null, undefined, 42, 'str', { id: 1, episode_number: 1, name: 'Pilot', runtime: 45 }] },
      { id: 103, episodes: [{ id: 2, episode_number: null, name: null, vote_average: '7.5' }] }
    ];

    for (const fix of episodeFixtures) {
      global.fetch = () => Promise.resolve({
        ok: true,
        json: () => Promise.resolve(fix)
      });

      const season = await tmdb.getTvSeason(fix.id, 1);
      assert.ok(season && Array.isArray(season.episodes), 'Season episodes must be array');
    }
  });

  // ADV-S4.14
  await check('DEFECT', 'ADV-S4.14', 'CardFactory.createPosterCard robustness under null, undefined, empty, and corrupted items', async function () {
    const dom = new JSDOM('<!DOCTYPE html><html><body><div id="test-container"></div></body></html>', { runScripts: 'dangerously' });
    const code = fs.readFileSync(path.resolve(__dirname, '../app/js/views/home.js'), 'utf8');
    dom.window.eval(code);

    const CF = dom.window.CardFactory;
    assert.ok(CF, 'CardFactory must be exposed');

    const testItems = [
      null,
      undefined,
      {},
      { id: 1 },
      { id: 2, title: 12345 },
      { id: 3, release_date: 2024 },
      { id: 4, vote_average: 8.5 },
      { id: 5, vote_average: 0 },
      { id: 6, genres: null },
      { id: 7, genres: 'Action' },
      { id: 8, genres: ['Action', 'Thriller'] },
      { id: 9, poster_path: null, posterUrl: null }
    ];

    for (let i = 0; i < testItems.length; i++) {
      const it = testItems[i];
      let card = null;
      assert.doesNotThrow(() => {
        card = CF.createPosterCard(it, 'test-group', i);
      }, `CardFactory must not throw for item at index ${i}`);
      assert.ok(card instanceof dom.window.Node, 'Must return a valid DOM Node');
    }
  });

  // ===========================================================================
  // SUITE 2: Edge Case Fuzzing on TMDB Response Structures
  // ===========================================================================
  console.log(`\n${C.cyan}▶ SUITE 2: Edge Case Fuzzing on TMDB Response Structures${C.reset}`);

  await check('FUZZ', 'NESTED', 'Deeply nested corrupted payloads and null sub-arrays in normalizeDetails', async function () {
    const tmdb = createFreshTmdb();

    const nestedCorrupted = {
      id: 555,
      title: 'Deeply Corrupted',
      overview: null,
      runtime: null,
      episode_run_time: 'not an array',
      seasons: [
        null,
        undefined,
        'invalid season',
        123,
        { season_number: -1 }, // Should be excluded (<= 0)
        { id: 10, season_number: 1, name: null, episode_count: null, poster_path: null }
      ],
      credits: {
        cast: [
          null,
          { id: 1, name: 'Actor 1', profile_path: null, order: null },
          'Actor Name As String',
          { id: 2, name: null, character: null }
        ]
      },
      recommendations: {
        results: [
          null,
          { id: 556, title: null, release_date: null, genre_ids: null }
        ]
      },
      similar: {
        results: 'corrupted string results'
      },
      images: {
        logos: [
          null,
          { file_path: null },
          { file_path: '/logo_de.png', iso_639_1: 'de' }
        ]
      }
    };

    let details = null;
    assert.doesNotThrow(() => {
      details = tmdb.normalizeDetails(nestedCorrupted);
    });

    assert.ok(details, 'Details must be returned');
    assert.strictEqual(details.id, 555);
    assert.strictEqual(details.runtime, 0);
    assert.strictEqual(details.formattedRuntime, '—');
    assert.strictEqual(details.seasons.length, 1, 'Only positive valid seasons retained');
    assert.strictEqual(details.seasons[0].seasonNumber, 1);
    assert.strictEqual(details.seasons[0].name, 'Season 1');
    assert.strictEqual(details.recommendations.length, 1);
    assert.strictEqual(details.similar.length, 0);
    assert.strictEqual(details.logoUrl, 'https://image.tmdb.org/t/p/w500/logo_de.png');
  });

  await check('FUZZ', 'DATES', 'Extreme release date formats (ISO, B.C., timestamps, future, unicode)', async function () {
    const tmdb = createFreshTmdb();

    const extremeDates = [
      { raw: '2026-11-04T12:00:00.000Z', expected: '2026' },
      { raw: '2099-01-01', expected: '2099' },
      { raw: '-0044-03-15', expected: '-004' },
      { raw: '1970', expected: '1970' },
      { raw: 'Unknown date', expected: 'Unkn' },
      { raw: '   2021   ', expected: '   2' }
    ];

    for (const ed of extremeDates) {
      const item = tmdb.normalizeItem({ id: 1, release_date: ed.raw });
      assert.strictEqual(item.year, ed.expected, `Expected year ${ed.expected} for ${ed.raw}`);
    }
  });

  await check('FUZZ', 'CAST', 'Non-object cast members (primitives, arrays, symbols, nulls) in credits', async function () {
    const tmdb = createFreshTmdb();

    const raw = {
      id: 99,
      title: 'Movie',
      credits: {
        cast: [
          null,
          undefined,
          'A String',
          42,
          true,
          false,
          [1, 2, 3],
          { id: 50, name: 'Valid Actor', profile_path: '/profile.jpg', order: 1 }
        ]
      }
    };

    let details = null;
    assert.doesNotThrow(() => {
      details = tmdb.normalizeDetails(raw);
    });

    assert.ok(details && Array.isArray(details.cast), 'Cast must be array');
    const validMember = details.cast.find(m => m.id === 50);
    assert.ok(validMember, 'Valid member must be extracted');
    assert.strictEqual(validMember.name, 'Valid Actor');
  });

  // ===========================================================================
  // SUITE 3: Cache Memory Bounds & LRU Stress
  // ===========================================================================
  console.log(`\n${C.cyan}▶ SUITE 3: Cache Memory Bounds & LRU Stress (~350KB Limit)${C.reset}`);

  await check('CACHE', 'CAPACITY', 'Strict 100-entry ceiling during 1,000 continuous insertions', async function () {
    const tmdb = createFreshTmdb({ cacheCapacity: 100 });
    tmdb.clearCache();

    global.fetch = (url) => {
      const match = url.match(/page=(\d+)/);
      const p = match ? match[1] : '1';
      return Promise.resolve({
        ok: true,
        json: () => Promise.resolve({ page: parseInt(p, 10), results: [{ id: parseInt(p, 10), title: `Movie ${p}` }] })
      });
    };

    for (let i = 1; i <= 1000; i++) {
      await tmdb.discover('movie', { page: i });
    }

    const stats = tmdb.getCacheStats();
    assert.strictEqual(stats.size, 100, `Cache size must remain capped at exactly 100 entries. Got: ${stats.size}`);
    assert.strictEqual(stats.evictions, 900, `Must record exactly 900 evictions. Got: ${stats.evictions}`);
    assert.strictEqual(stats.misses, 1000, `Must record 1000 misses. Got: ${stats.misses}`);
  });

  await check('CACHE', 'LRU_ORDER', 'LRU re-ordering preserves accessed items and evicts oldest unaccessed', async function () {
    const tmdb = createFreshTmdb({ cacheCapacity: 4 });
    tmdb.clearCache();

    global.fetch = (url) => {
      const match = url.match(/page=(\d+)/);
      const p = match ? match[1] : '1';
      return Promise.resolve({
        ok: true,
        json: () => Promise.resolve({ page: parseInt(p, 10), results: [{ id: parseInt(p, 10) }] })
      });
    };

    // Insert 1, 2, 3, 4
    await tmdb.discover('movie', { page: 1 });
    await tmdb.discover('movie', { page: 2 });
    await tmdb.discover('movie', { page: 3 });
    await tmdb.discover('movie', { page: 4 });

    // Touch 1 and 2 to move them to MRU
    await tmdb.discover('movie', { page: 1 });
    await tmdb.discover('movie', { page: 2 });

    // Insert 5 -> should evict 3 (oldest unaccessed)
    await tmdb.discover('movie', { page: 5 });

    const stats = tmdb.getCacheStats();
    assert.strictEqual(stats.evictions, 1, 'Should have evicted 1 item');

    // Reset fetch to verify hits vs misses
    let fetchedPages = [];
    global.fetch = (url) => {
      const match = url.match(/page=(\d+)/);
      const p = match ? match[1] : '1';
      fetchedPages.push(p);
      return Promise.resolve({
        ok: true,
        json: () => Promise.resolve({ page: parseInt(p, 10), results: [{ id: parseInt(p, 10) }] })
      });
    };

    // 1 and 2 should still be cached (no fetch)
    await tmdb.discover('movie', { page: 1 });
    await tmdb.discover('movie', { page: 2 });
    assert.strictEqual(fetchedPages.length, 0, 'Pages 1 and 2 must be cache hits');

    // 3 was evicted -> must fetch
    await tmdb.discover('movie', { page: 3 });
    assert.strictEqual(fetchedPages.length, 1, 'Page 3 must be a cache miss/fetch');
    assert.strictEqual(fetchedPages[0], '3');
  });

  await check('CACHE', 'MEMORY_BUDGET', '100 realistic full TMDB responses footprint is bounded (~350KB - 450KB)', async function () {
    const tmdb = createFreshTmdb({ cacheCapacity: 100 });
    tmdb.clearCache();

    // Standard 20-item TMDB discovery response payload
    const standardFeedItem = {
      backdrop_path: '/b33nnkl92348k.jpg',
      genre_ids: [28, 12, 878],
      id: 693134,
      original_language: 'en',
      original_title: 'Dune: Part Two',
      overview: 'Follow the mythic journey of Paul Atreides as he unites with Chani and the Fremen while on a warpath of revenge against the conspirators who destroyed his family.',
      popularity: 642.345,
      poster_path: '/czembW0Rk1Ke7lCJGhkAiAhQ9Ud.jpg',
      release_date: '2024-02-27',
      title: 'Dune: Part Two',
      video: false,
      vote_average: 8.2,
      vote_count: 5120
    };

    const feedPayload = {
      page: 1,
      results: Array.from({ length: 20 }, (_, idx) => Object.assign({}, standardFeedItem, { id: 693134 + idx, title: `Movie Title #${idx}` })),
      total_pages: 500,
      total_results: 10000
    };

    global.fetch = (url) => {
      const match = url.match(/page=(\d+)/);
      const p = match ? parseInt(match[1], 10) : 1;
      return Promise.resolve({
        ok: true,
        json: () => Promise.resolve(Object.assign({}, feedPayload, { page: p }))
      });
    };

    for (let p = 1; p <= 100; p++) {
      await tmdb.discover('movie', { page: p });
    }

    const singleSize = Buffer.byteLength(JSON.stringify(feedPayload), 'utf8');
    const totalSerializedSize = singleSize * 100;
    const totalKb = totalSerializedSize / 1024;

    console.log(`    ${C.gray}Single Feed: ${singleSize} bytes. 100 Entries Serialized: ${totalKb.toFixed(1)} KB${C.reset}`);
    assert.ok(totalKb <= 480, `100 entries must fit within webOS ~350KB-480KB memory envelope (got: ${totalKb.toFixed(1)} KB)`);
  });

  // ===========================================================================
  // SUITE 4: Timeouts & AbortController (8000ms Default Timeout)
  // ===========================================================================
  console.log(`\n${C.cyan}▶ SUITE 4: Timeouts & AbortController (8000ms Default Timeout)${C.reset}`);

  await check('TIMEOUT', 'CONFIG', 'Default timeout is strictly configured to 8000ms', async function () {
    const tmdb = createFreshTmdb();
    const cfg = tmdb.getConfig();
    assert.strictEqual(cfg.requestTimeoutMs, 8000, `Default timeout must be 8000ms (got: ${cfg.requestTimeoutMs})`);
  });

  await check('TIMEOUT', 'ABORT_SIGNAL', 'Hanging fetch triggers AbortController abort signal and cleans up timer', async function () {
    const tmdb = createFreshTmdb({ requestTimeoutMs: 80 });
    tmdb.clearCache();

    let signalAborted = false;
    let receivedSignal = null;

    global.fetch = (url, opts) => {
      receivedSignal = opts && opts.signal;
      if (receivedSignal) {
        receivedSignal.addEventListener('abort', () => {
          signalAborted = true;
        });
      }
      return new Promise(() => {}); // Never resolves
    };

    const start = Date.now();
    const res = await tmdb.getTrending('movie', 'day');
    const elapsed = Date.now() - start;

    assert.ok(elapsed >= 75 && elapsed < 300, `Timeout must trigger near 80ms (took ${elapsed}ms)`);
    assert.ok(res && res.error, 'Must return structured error object');
    assert.strictEqual(res.code, 'TIMEOUT');
    assert.strictEqual(signalAborted, true, 'AbortController signal must have triggered abort');
    assert.ok(receivedSignal && receivedSignal.aborted, 'signal.aborted must be true');
  });

  await check('TIMEOUT', 'FAST_SUCCESS_CLEANUP', 'Fast responses resolve cleanly without timeout firing', async function () {
    const tmdb = createFreshTmdb({ requestTimeoutMs: 200 });
    tmdb.clearCache();

    global.fetch = () => Promise.resolve({
      ok: true,
      json: () => Promise.resolve({ page: 1, results: [{ id: 1, title: 'Speedy' }] })
    });

    const res = await tmdb.getTrending('movie', 'day');
    assert.ok(res && !res.error, 'Fast response must succeed');
    assert.strictEqual(res.results.length, 1);
    assert.strictEqual(res.results[0].title, 'Speedy');
  });

  await check('TIMEOUT', 'STALE_FALLBACK', 'Unresponsive network timeout falls back to stale cache', async function () {
    const tmdb = createFreshTmdb({ requestTimeoutMs: 60 });
    tmdb.clearCache();

    // 1. Prime cache with TTL = 0 (immediately stale)
    global.fetch = () => Promise.resolve({
      ok: true,
      json: () => Promise.resolve({ page: 1, results: [{ id: 777, title: 'Stale Treasure' }] })
    });

    // Populate with 0 second TTL
    await tmdb.getTrending('movie', 'day');

    // Wait 5ms so it is officially expired
    await new Promise(r => setTimeout(r, 10));

    // 2. Network now hangs indefinitely
    global.fetch = () => new Promise(() => {});

    // Must return stale entry rather than error
    const res = await tmdb.getTrending('movie', 'day');
    assert.ok(res && !res.error, 'Must serve stale entry on timeout');
    assert.strictEqual(res.results.length, 1);
    assert.strictEqual(res.results[0].title, 'Stale Treasure');
  });

  // ===========================================================================
  // Summary
  // ===========================================================================
  console.log(`\n${C.bold}========================================================================${C.reset}`);
  console.log(`${C.bold}Adversarial Empirical Stress Test Summary:${C.reset}`);
  console.log(`  Total Checks:   ${totalChecks}`);
  console.log(`  Passed Checks:  ${C.green}${passedChecks}${C.reset}`);
  console.log(`  Failed Checks:  ${failedChecks > 0 ? C.red : C.green}${failedChecks}${C.reset}`);
  console.log(`${C.bold}========================================================================${C.reset}\n`);

  if (failedChecks > 0) {
    console.log(`${C.red}VERDICT: FAIL - ${failedChecks} EMPIRICAL CHECKS FAILED${C.reset}`);
    failureList.forEach(f => {
      console.log(`  - ${f.label}`);
      console.log(`    ${f.error}`);
    });
    process.exit(1);
  } else {
    console.log(`${C.green}VERDICT: ALL ${passedChecks} ADVERSARIAL STRESS & FUZZING CHECKS PASSED (100%)${C.reset}\n`);
    process.exit(0);
  }
}

runEmpiricalStressSuite().catch(err => {
  console.error('Fatal unhandled error:', err);
  process.exit(1);
});

